def process(d):
    r = []
    for i in range(len(d)):
        f = True
        for j in range(len(r)):
            if d[i] == r[j]:
                f = False
                break
        if f:
            r.append(d[i])
    s = 0
    for x in r:
        s = s + x
    return s / len(r)

